use vstd::prelude::*;

verus! {

/// A simple slice descriptor: optional start/stop/step.
/// (This is analogous to Python-like slicing descriptors.)
pub struct Slice {
    pub start: Option<usize>,
    pub stop:  Option<usize>,
    pub step:  Option<usize>,
}

/// Spec predicate capturing the required well-formedness constraints.
pub open spec fn slice_wf(start: Option<usize>, stop: Option<usize>, step: Option<usize>) -> bool {
    // If step is provided, it must be strictly positive.
    (match step {
        None => true,
        Some(s) => s > 0,
    })
    &&
    // If both start and stop are provided, require start <= stop.
    (match (start, stop) {
        (Some(a), Some(b)) => a <= b,
        _ => true,
    })
}

/// Construct a `Slice` whose fields exactly match the inputs,
/// and preserve the given constraints.
pub fn s_(start: Option<usize>, stop: Option<usize>, step: Option<usize>) -> (slice: Slice)
    requires
        slice_wf(start, stop, step),
    ensures
        slice.start == start,
        slice.stop  == stop,
        slice.step  == step,
        slice_wf(slice.start, slice.stop, slice.step),
{
    let slice = Slice { start, stop, step };

    // Establish the returned object respects the same constraints.
    // This is immediate because fields are exactly the inputs.
    assert(slice_wf(slice.start, slice.stop, slice.step));

    slice
}

} // verus!

